                    let subquery = self.parse_select_stmt()?;
                    if matches!(
                        self.peek().kind,
                        TokenKind::Keyword(Keyword::UNION)
                            | TokenKind::Keyword(Keyword::INTERSECT)
                            | TokenKind::Keyword(Keyword::EXCEPT)
