        Ok(idx) => KEYWORDS
            .get(idx)
            .map(|(_, kw)| TokenKind::Keyword(*kw))
            .unwrap_or_else(|| TokenKind::Identifier(word.to_string())),
        Err(_) => TokenKind::Identifier(word.to_string()),
